interface IChatModel { Task<string> CompleteAsync(List<(string Role, string Text)> messages); }

class Explainer(IChatModel model)
{
    public Task<string> ExplainAsync(string topic) =>
        model.CompleteAsync([("system", "Explain in one sentence."), ("user", $"Explain: {topic}")]);
}

class FakeModel(string answer) : IChatModel
{
    public List<(string Role, string Text)> LastMessages { get; private set; } = [];
    public Task<string> CompleteAsync(List<(string Role, string Text)> messages)
    {
        LastMessages = messages;
        return Task.FromResult(answer);
    }
}

