using System.Text.Json;

string[] categories = ["billing", "bug", "account", "feature", "other"];
string[] answers =
[
    """{"category":"billing","priority":3,"summary":"Charged twice for May"}""",
    """{"category":"refund","priority":9,"summary":""}""",
];

foreach (var json in answers)
{
    var t = JsonSerializer.Deserialize<Triage>(json, JsonSerializerOptions.Web)!;
    var errors = new List<string>();
    if (!categories.Contains(t.Category)) errors.Add($"unknown category '{t.Category}'");
    if (t.Priority is < 1 or > 5) errors.Add($"priority {t.Priority} out of range");
    if (string.IsNullOrWhiteSpace(t.Summary)) errors.Add("empty summary");
    Console.WriteLine(errors.Count == 0 ? $"OK: {t.Category} P{t.Priority}" : "Rejected: " + string.Join(", ", errors));
}

