static async Task<string> SlowModelAsync(CancellationToken ct)
{
    await Task.Delay(TimeSpan.FromSeconds(5), ct);
    return "A very late answer";
}

static bool IsTransient(int status) => status is 429 or 408 || status >= 500;
static TimeSpan Backoff(int attempt) => TimeSpan.FromSeconds(Math.Pow(2, attempt - 1));   // 1s, 2s, 4s

int[] responses = [503, 429, 200];
for (var attempt = 1; attempt <= responses.Length; attempt++)
{
    var status = responses[attempt - 1];
    if (status == 200) { Console.WriteLine($"Attempt {attempt}: success"); break; }
    Console.WriteLine(IsTransient(status)
        ? $"Attempt {attempt}: {status}, retry in {Backoff(attempt).TotalSeconds}s"
        : $"Attempt {attempt}: {status}, give up");
}
Console.WriteLine($"401 transient? {IsTransient(401)}");

decimal inPrice = 0.50m, outPrice = 1.50m;   // dollars per million tokens
var calls = new[]
{
    (Feature: "tutor", User: "sara", In: 1_200, Out: 300),
    (Feature: "tutor", User: "omar", In: 900, Out: 250),
    (Feature: "summary", User: "sara", In: 6_000, Out: 400),
    (Feature: "tutor", User: "sara", In: 1_500, Out: 350),
};

foreach (var g in calls.GroupBy(c => c.Feature))
{
    var cost = g.Sum(c => c.In * inPrice / 1_000_000m + c.Out * outPrice / 1_000_000m);
    Console.WriteLine($"{g.Key}: {g.Count()} calls, {g.Sum(c => c.In + c.Out)} tokens, ${cost:0.00000}");
}

public async Task<IResult> AskAsync(string userId, string question, CancellationToken ct)
{
    if (await usage.TokensTodayAsync(userId, ct) >= options.Value.DailyTokensPerUser)
        return Results.Problem(statusCode: 429, title: "You've used today's AI allowance. It resets at midnight.");

    var response = await chat.GetResponseAsync(Messages(question), new ChatOptions { MaxOutputTokens = 400 }, ct);
    await usage.RecordAsync(userId, "tutor", response.Usage, ct);
    return Results.Ok(response.Text);
}

