using System.Text.Json;

var fakes = new (string Name, Func<Task<string>> Reply)[]
{
    ("good", () => Task.FromResult("""{"explanation":"A key that points to another table."}""")),
    ("invalid", () => Task.FromResult("Sure! Here is your answer...")),
    ("timeout", () => Task.FromException<string>(new TaskCanceledException())),
};

foreach (var (name, reply) in fakes)
    Console.WriteLine($"{name}: {await Handle(reply)}");

static async Task<string> Handle(Func<Task<string>> callModel)
{
    try
    {
        var json = await callModel();
        var doc = JsonDocument.Parse(json);
        return "200 " + doc.RootElement.GetProperty("explanation").GetString();
    }
    catch (JsonException) { return "502 unusable answer"; }
    catch (OperationCanceledException) { return "503 try again later"; }
}
